return [
  {
    json: {
      id: "ALERT-0001",
      name: "Impossible travel detected",
      description: "User authenticated from geographically distant locations within an unusual time window.",
      severity: "High",

      vendor: "Microsoft",
      product: "Microsoft Defender XDR",

      category: "Identity",

      timestamp: "2026-08-23T17:30:00Z",

      user: "john.doe@example.com",
      host: "WIN11-LAPTOP-01",

      source_ip: "185.220.101.20",
      destination_ip: "20.190.128.25",

      additional_data: {
        country_a: "Spain",
        country_b: "Netherlands",
        authentication_method: "MFA",
        device_managed: false
      }
    }
  }
];

const input = $json;

// -----------------------------
// Helper functions
// -----------------------------

function normalizeSeverity(value) {
  if (!value) return "unknown";

  const severity = String(value).toLowerCase().trim();

  const severityMap = {
    info: "informational",
    informational: "informational",
    low: "low",
    medium: "medium",
    moderate: "medium",
    high: "high",
    critical: "critical",
    severe: "critical"
  };

  return severityMap[severity] || "unknown";
}

function normalizeCategory(value) {
  if (!value) return "unknown";

  const category = String(value).toLowerCase().trim();

  const categoryMap = {
    identity: "identity",
    iam: "identity",
    authentication: "identity",

    endpoint: "endpoint",
    edr: "endpoint",
    host: "endpoint",

    network: "network",
    firewall: "network",

    email: "email",
    mail: "email",
    phishing: "email",

    cloud: "cloud",
    azure: "cloud",
    aws: "cloud",
    gcp: "cloud",

    data: "data",
    dlp: "data",

    application: "application",
    app: "application",

    other: "other"
  };

  return categoryMap[category] || "unknown";
}

function addUniqueString(array, value) {
  if (
    value !== undefined &&
    value !== null &&
    String(value).trim() !== ""
  ) {
    const normalizedValue = String(value).trim();

    if (!array.includes(normalizedValue)) {
      array.push(normalizedValue);
    }
  }
}

function addUniqueIp(array, value, role) {
  if (
    value === undefined ||
    value === null ||
    String(value).trim() === ""
  ) {
    return;
  }

  const ip = String(value).trim();

  const exists = array.some(
    item => item.value === ip && item.role === role
  );

  if (!exists) {
    array.push({
      value: ip,
      role
    });
  }
}

// -----------------------------
// Entities
// -----------------------------

const users = [];
const hosts = [];
const ips = [];

addUniqueString(users, input.user);
addUniqueString(hosts, input.host);

addUniqueIp(ips, input.source_ip, "source");
addUniqueIp(ips, input.destination_ip, "destination");

// -----------------------------
// Canonical alert
// -----------------------------

const normalizedAlert = {
  schema_version: "1.0",

  alert_id: String(input.id || "").trim(),
  title: String(input.name || "").trim(),
  description: String(input.description || "").trim(),

  severity: normalizeSeverity(input.severity),
  category: normalizeCategory(input.category),

  source: {
    vendor: String(input.vendor || "").trim(),
    product: String(input.product || "").trim(),
    integration: "manual"
  },

  // Do not call toISOString() before validation
  event_time: input.timestamp
    ? String(input.timestamp).trim()
    : new Date().toISOString(),

  entities: {
    users,
    hosts,
    ips
  },

  iocs: [],

  metadata: {
    additional_data: input.additional_data || {}
  },

  raw_alert: input
};

// -----------------------------
// Validation
// -----------------------------

const validationErrors = [];

if (!normalizedAlert.alert_id) {
  validationErrors.push("alert_id is required");
}

if (!normalizedAlert.title) {
  validationErrors.push("title is required");
}

if (!normalizedAlert.source.vendor) {
  validationErrors.push("source.vendor is required");
}

if (!normalizedAlert.source.product) {
  validationErrors.push("source.product is required");
}

if (
  !normalizedAlert.event_time ||
  Number.isNaN(Date.parse(normalizedAlert.event_time))
) {
  validationErrors.push(
    "event_time must be a valid ISO 8601 timestamp"
  );
}

// -----------------------------
// Reject invalid alerts
// -----------------------------

if (validationErrors.length > 0) {
  throw new Error(
    `Alert validation failed: ${validationErrors.join("; ")}`
  );
}

// -----------------------------
// Final normalization
// -----------------------------

normalizedAlert.event_time =
  new Date(normalizedAlert.event_time).toISOString();

// -----------------------------
// n8n output
// -----------------------------

return [
  {
    json: normalizedAlert
  }
];

const alert = $json;

// --------------------------------------------------
// 1. Extract explicit IP roles
// --------------------------------------------------

const sourceIps = [];
const destinationIps = [];
const relatedIps = [];

for (const ip of alert.entities?.ips || []) {
  if (!ip?.value) {
    continue;
  }

  switch (ip.role) {
    case "source":
      sourceIps.push(ip.value);
      break;

    case "destination":
      destinationIps.push(ip.value);
      break;

    default:
      relatedIps.push(ip.value);
      break;
  }
}

// --------------------------------------------------
// 2. Extract provider-specific context
// --------------------------------------------------

const additionalData =
  alert.metadata?.additional_data || {};

// --------------------------------------------------
// 3. Build geographic observations
// --------------------------------------------------
//
// IMPORTANT:
//
// country_a and country_b are provider observations.
//
// The current alert does NOT explicitly establish:
//   source_ip      -> country_a
//   destination_ip -> country_b
//
// Therefore locations are intentionally represented
// separately from IP entities.
// --------------------------------------------------

const reportedLocations = [];

if (
  additionalData.country_a !== undefined &&
  additionalData.country_a !== null &&
  String(additionalData.country_a).trim() !== ""
) {
  reportedLocations.push(
    String(additionalData.country_a).trim()
  );
}

if (
  additionalData.country_b !== undefined &&
  additionalData.country_b !== null &&
  String(additionalData.country_b).trim() !== ""
) {
  const location =
    String(additionalData.country_b).trim();

  if (!reportedLocations.includes(location)) {
    reportedLocations.push(location);
  }
}

// --------------------------------------------------
// 4. Build investigation context
// --------------------------------------------------

const investigationContext = {
  context_version: "1.0",

  task: "initial_security_alert_analysis",

  instructions: {
    objective:
      "Perform an initial SOC triage using only explicitly provided evidence.",

    evidence_policy: [
      "Treat only explicitly provided fields and relationships as observed evidence.",
      "Do not infer relationships between independent fields.",
      "Do not associate geographic locations with IP addresses unless that mapping is explicitly provided.",
      "Do not state that a user authenticated from a specific country unless the input explicitly establishes that relationship.",
      "Do not invent missing events, activity, users, devices, threat intelligence, authentication details, or geographic relationships.",
      "Keep observed evidence separate from hypotheses.",
      "Identify missing evidence required for further investigation."
    ]
  },

  alert: {
    schema_version:
      alert.schema_version,

    identity: {
      alert_id:
        alert.alert_id,

      title:
        alert.title,

      description:
        alert.description
    },

    classification: {
      severity:
        alert.severity,

      category:
        alert.category
    },

    source: {
      vendor:
        alert.source?.vendor || null,

      product:
        alert.source?.product || null,

      integration:
        alert.source?.integration || null
    },

    timing: {
      event_time:
        alert.event_time
    },

    entities: {
      users:
        alert.entities?.users || [],

      hosts:
        alert.entities?.hosts || [],

      source_ips:
        sourceIps,

      destination_ips:
        destinationIps,

      related_ips:
        relatedIps
    },

    iocs:
      alert.iocs || [],

    provider_context: {
      authentication_method:
        additionalData.authentication_method ?? null,

      device_managed:
        additionalData.device_managed ?? null,

      geographic_observations: {
        reported_locations:
          reportedLocations,

        relationship_to_ip_addresses:
          "unknown",

        relationship_to_user_authentication:
          "not_explicitly_provided"
      }
    }
  },

  evidence_constraints: {
    geographic_mapping_explicit:
      false,

    geographic_user_relationship_explicit:
      false,

    threat_intelligence_available:
      false,

    historical_signins_available:
      false,

    endpoint_activity_available:
      false,

    post_authentication_activity_available:
      false
  }
};

// --------------------------------------------------
// 5. Output
// --------------------------------------------------

return [
  {
    json: investigationContext
  }
];

const context = $json;

// --------------------------------------------------
// 1. Expected canonical output
// --------------------------------------------------

const expectedOutput = {
  analysis_version: "1.0",

  alert_id:
    context.alert?.identity?.alert_id || "",

  summary:
    "Concise non-empty summary based only on explicit evidence.",

  observed_evidence: [
    {
      field: "example_field",
      value: "example_value"
    }
  ],

  hypotheses: [],

  risk_assessment: {
    level: "unknown",
    reasoning: []
  },

  missing_evidence: [],

  preliminary_verdict:
    "inconclusive",

  confidence:
    0,

  recommended_investigations: []
};

// --------------------------------------------------
// 2. System prompt
// --------------------------------------------------

const systemPrompt =
  "You are a cybersecurity SOC analyst. " +

  "Your analysis must be evidence-grounded and conservative. " +

  "Use only facts and relationships explicitly represented in the investigation context. " +

  "Never create a relationship between two pieces of evidence merely because both are present in the input. " +

  "Never convert an observation into a stronger claim than the source evidence supports. " +

  "Keep observed evidence strictly separate from hypotheses. " +

  "Return only valid JSON. " +

  "Do not use Markdown, code fences, comments, or explanatory text outside the JSON object.";

// --------------------------------------------------
// 3. User prompt
// --------------------------------------------------

const userPrompt =
  "Perform an initial SOC triage using the provided investigation context. " +

  "Return exactly one JSON object matching this structure: " +
  JSON.stringify(expectedOutput) +
  ". " +

  "MANDATORY EVIDENCE RULES: " +

  "1. analysis_version must be exactly '1.0'. " +

  "2. alert_id must exactly match the provided alert ID. " +

  "3. summary must be a concise non-empty description based only on explicitly supported facts. " +

  "4. observed_evidence must contain only facts explicitly present in the investigation context. " +

  "5. Each observed_evidence entry must contain field and value. " +

  "6. Preserve the original JSON type of observed values whenever possible. " +

  "7. Do not infer relationships between independent fields. " +

  "8. Geographic observations are NOT automatically associated with source IPs, destination IPs, users, hosts, or authentication events. " +

  "9. If geographic_observations.relationship_to_ip_addresses is 'unknown', you MUST NOT state or imply that any IP belongs to any reported location. " +

  "10. If geographic_observations.relationship_to_user_authentication is 'not_explicitly_provided', you MUST NOT state that the user authenticated from those countries or locations. " +

  "11. You may state that the provider context contains geographic observations for the listed locations, but their relationship to IP addresses or authentication events is unknown. " +

  "12. hypotheses may contain plausible explanations, but they must never be presented as observed facts. " +

  "13. risk_assessment.level must be one of: low, medium, high, critical, unknown. " +

  "14. risk_assessment.reasoning must use only observed evidence and clearly identified uncertainty. " +

  "15. preliminary_verdict must be one of: benign, suspicious, malicious, inconclusive. " +

  "16. confidence must be a number between 0 and 1 representing confidence in the preliminary analysis using only currently available evidence. " +

  "17. missing_evidence must contain human-readable descriptions. Never expose internal variable names such as historical_signins_available or geographic_mapping_explicit. " +

  "18. recommended_investigations must describe concrete evidence that should be collected next. " +

  "19. If evidence_constraints indicates that information is unavailable, treat that information as missing evidence. Never assume its value. " +

  "Investigation context: " +
  JSON.stringify(context);

// --------------------------------------------------
// 4. Ollama request
// --------------------------------------------------

return [
  {
    json: {
      model: "qwen3:8b",

      messages: [
        {
          role: "system",
          content: systemPrompt
        },
        {
          role: "user",
          content: userPrompt
        }
      ],

      stream: false,

      think: false,

      keep_alive: "5m",

      format: "json"
    }
  }
];

const response = $json;

// --------------------------------------------------
// 1. Extract LLM response
// --------------------------------------------------

const content = response?.message?.content;

if (!content || typeof content !== "string") {
  throw new Error(
    "LLM analysis validation failed: message.content is missing or empty"
  );
}

// --------------------------------------------------
// 2. Parse JSON
// --------------------------------------------------

let analysis;

try {
  analysis = JSON.parse(content);
} catch (error) {
  throw new Error(
    `LLM analysis validation failed: response is not valid JSON: ${error.message}`
  );
}

// --------------------------------------------------
// 3. Validation helpers
// --------------------------------------------------

const errors = [];

function requireString(field, value) {
  if (typeof value !== "string" || value.trim() === "") {
    errors.push(`${field} must be a non-empty string`);
  }
}

function requireArray(field, value) {
  if (!Array.isArray(value)) {
    errors.push(`${field} must be an array`);
  }
}

function validateStringArray(field, value) {
  if (!Array.isArray(value)) {
    errors.push(`${field} must be an array`);
    return;
  }

  value.forEach((item, index) => {
    if (typeof item !== "string") {
      errors.push(
        `${field}[${index}] must be a string`
      );
    }
  });
}

// --------------------------------------------------
// 4. Top-level validation
// --------------------------------------------------

if (analysis.analysis_version !== "1.0") {
  errors.push("analysis_version must be '1.0'");
}

requireString(
  "alert_id",
  analysis.alert_id
);

requireString(
  "summary",
  analysis.summary
);

requireArray(
  "observed_evidence",
  analysis.observed_evidence
);

validateStringArray(
  "hypotheses",
  analysis.hypotheses
);

validateStringArray(
  "missing_evidence",
  analysis.missing_evidence
);

validateStringArray(
  "recommended_investigations",
  analysis.recommended_investigations
);

// --------------------------------------------------
// 5. observed_evidence validation
// --------------------------------------------------

if (Array.isArray(analysis.observed_evidence)) {
  analysis.observed_evidence.forEach(
    (evidence, index) => {

      if (
        typeof evidence !== "object" ||
        evidence === null ||
        Array.isArray(evidence)
      ) {
        errors.push(
          `observed_evidence[${index}] must be an object`
        );
        return;
      }

      requireString(
        `observed_evidence[${index}].field`,
        evidence.field
      );

      const value = evidence.value;

      const validPrimitiveTypes = [
        "string",
        "number",
        "boolean"
      ];

      if (value === null) {
        return;
      }

      if (Array.isArray(value)) {
        const invalidArrayValue = value.some(
          item =>
            item !== null &&
            !validPrimitiveTypes.includes(
              typeof item
            )
        );

        if (invalidArrayValue) {
          errors.push(
            `observed_evidence[${index}].value array contains an invalid type`
          );
        }

        return;
      }

      if (
        !validPrimitiveTypes.includes(
          typeof value
        )
      ) {
        errors.push(
          `observed_evidence[${index}].value has invalid type`
        );
      }
    }
  );
}

// --------------------------------------------------
// 6. Risk assessment validation
// --------------------------------------------------

const validRiskLevels = [
  "low",
  "medium",
  "high",
  "critical",
  "unknown"
];

if (
  typeof analysis.risk_assessment !== "object" ||
  analysis.risk_assessment === null ||
  Array.isArray(analysis.risk_assessment)
) {
  errors.push(
    "risk_assessment must be an object"
  );
} else {
  if (
    !validRiskLevels.includes(
      analysis.risk_assessment.level
    )
  ) {
    errors.push(
      "risk_assessment.level contains an invalid value"
    );
  }

  validateStringArray(
    "risk_assessment.reasoning",
    analysis.risk_assessment.reasoning
  );
}

// --------------------------------------------------
// 7. Preliminary verdict validation
// --------------------------------------------------

const validVerdicts = [
  "benign",
  "suspicious",
  "malicious",
  "inconclusive"
];

if (
  !validVerdicts.includes(
    analysis.preliminary_verdict
  )
) {
  errors.push(
    "preliminary_verdict contains an invalid value"
  );
}

// --------------------------------------------------
// 8. Confidence validation
// --------------------------------------------------

if (
  typeof analysis.confidence !== "number" ||
  Number.isNaN(analysis.confidence) ||
  analysis.confidence < 0 ||
  analysis.confidence > 1
) {
  errors.push(
    "confidence must be a number between 0 and 1"
  );
}

// --------------------------------------------------
// 9. Reject invalid response
// --------------------------------------------------

if (errors.length > 0) {
  throw new Error(
    `LLM analysis validation failed: ${errors.join("; ")}`
  );
}

// --------------------------------------------------
// 10. Return canonical analysis
// --------------------------------------------------

return [
  {
    json: analysis
  }
];
